fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Promote to a wider integer type to avoid overflow when summing
    let total = r as i16 + g as i16 + b as i16;
    let max_count = r.max(g).max(b) as i16;
    2 * max_count <= total + 1
}

